/**
 * Indonesian strings. Typed `Record<MessageKey, string>`, so a key added to
 * `en.ts` without a translation fails `tsc` rather than rendering the English
 * text as if it were translated.
 *
 * Register: the same plain, operational tone as the English. Product nouns a
 * user already sees on screen (role, site, module) stay in their familiar form
 * rather than being forced into a dictionary translation.
 */
